    @media (forced-colors: active) {
      .quiz-card,
      .form-field,
      .choice,
      .status:not(:empty),
      button,
      .eyebrow {
        border: 1px solid CanvasText;
        box-shadow: none;
      }

      .choice:has(input:checked) {
        outline: 2px solid Highlight;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>
  <main id="main-content" class="page-shell">
    <section class="hero" aria-labelledby="page-title">
      <p class="eyebrow">Multi-select quiz</p>
      <h1 id="page-title">Computer Languages Quiz</h1>
      <p class="intro">Choose every answer that fits each question, then submit your selections.</p>
    </section>

    <div class="quiz-card" id="quiz-root">
      <form id="quiz-form" novalidate>
        <div class="form-field" data-component="QuizQuestion">
          <fieldset aria-describedby="language-types-help">
            <legend>1. Which of these are commonly used programming languages?</legend>
            <p class="help-text" id="language-types-help">Select all options that are programming languages. Some choices may be tools, formats, or markup instead.</p>
            <div class="choices">
              <label class="choice" for="language-types-0">
                <input id="language-types-0" type="checkbox" name="language-types" value="Python">
                <span>Python</span>
              </label>
              <label class="choice" for="language-types-1">
                <input id="language-types-1" type="checkbox" name="language-types" value="JavaScript">
                <span>JavaScript</span>
              </label>
              <label class="choice" for="language-types-2">
                <input id="language-types-2" type="checkbox" name="language-types" value="HTML">
                <span>HTML</span>
              </label>
              <label class="choice" for="language-types-3">
                <input id="language-types-3" type="checkbox" name="language-types" value="Ruby">
                <span>Ruby</span>
              </label>
            </div>
          </fieldset>
        </div>

        <div class="form-field" data-component="QuizQuestion">
          <fieldset>
            <legend>2. Which languages are commonly run in web browsers?</legend>
            <div class="choices">
              <label class="choice" for="web-languages-0">
                <input id="web-languages-0" type="checkbox" name="web-languages" value="JavaScript">
                <span>JavaScript</span>
              </label>
              <label class="choice" for="web-languages-1">
                <input id="web-languages-1" type="checkbox" name="web-languages" value="TypeScript after compilation">
                <span>TypeScript after compilation</span>
              </label>
              <label class="choice" for="web-languages-2">
                <input id="web-languages-2" type="checkbox" name="web-languages" value="Swift">
                <span>Swift</span>
              </label>
              <label class="choice" for="web-languages-3">
                <input id="web-languages-3" type="checkbox" name="web-languages" value="CSS">
                <span>CSS</span>
              </label>
            </div>
          </fieldset>
        </div>

        <div class="form-field" data-component="QuizQuestion">
          <fieldset>
            <legend>3. Which languages are often compiled before running?</legend>
            <div class="choices">
              <label class="choice" for="compiled-languages-0">
                <input id="compiled-languages-0" type="checkbox" name="compiled-languages" value="C">
                <span>C</span>
              </label>
              <label class="choice" for="compiled-languages-1">
                <input id="compiled-languages-1" type="checkbox" name="compiled-languages" value="Go">
                <span>Go</span>
              </label>
              <label class="choice" for="compiled-languages-2">
                <input id="compiled-languages-2" type="checkbox" name="compiled-languages" value="Rust">
                <span>Rust</span>
              </label>
              <label class="choice" for="compiled-languages-3">
                <input id="compiled-languages-3" type="checkbox" name="compiled-languages" value="Markdown">
                <span>Markdown</span>
              </label>
            </div>
          </fieldset>
        </div>

        <div class="actions">
          <button type="submit">Submit quiz</button>
          <p class="status" id="quiz-status" aria-live="polite"></p>
        </div>
      </form>
    </div>
  </main>

  <script>
    const quizQuestions = [
      {
        id: "language-types",
        prompt: "Which of these are commonly used programming languages?",
        helpText: "Select all options that are programming languages. Some choices may be tools, formats, or markup instead.",
        choices: ["Python", "JavaScript", "HTML", "Ruby"]
      },
      {
        id: "web-languages",
        prompt: "Which languages are commonly run in web browsers?",
        choices: ["JavaScript", "TypeScript after compilation", "Swift", "CSS"]
      },
      {
        id: "compiled-languages",
        prompt: "Which languages are often compiled before running?",
        choices: ["C", "Go", "Rust", "Markdown"]
      }
    ];

    function QuizApp({ questions, form, status }) {
      return {
        submit() {
          const answeredCount = getAnsweredQuestionCount(form, questions);
          status.textContent = `Quiz submitted. You answered ${answeredCount} of ${questions.length} questions.`;
        }
      };
    }

    function getAnsweredQuestionCount(form, questions) {
      return questions.filter((question) => {
        return form.querySelectorAll(`input[name="${question.id}"]:checked`).length > 0;
      }).length;
    }

    const quizForm = document.getElementById("quiz-form");
    const quizStatus = document.getElementById("quiz-status");
    const quizApp = QuizApp({
      questions: quizQuestions,
      form: quizForm,
      status: quizStatus
    });

    quizForm.addEventListener("submit", (event) => {
      event.preventDefault();
      quizApp.submit();
    });
  </script>
</body>
</html>
