  <title>Computer Languages Quiz</title>
  <style>
    :root {
      color-scheme: light;
      --bg: #f5f7fb;
      --surface: #ffffff;
      --surface-muted: #f8fafc;
      --text: #111827;
      --muted: #4b5563;
      --border: #d1d5db;
      --accent: #2563eb;
      --accent-strong: #1d4ed8;
      --accent-soft: #dbeafe;
      --ring: #111827;
      --success-bg: #ecfdf5;
      --success-border: #047857;
      --success-text: #064e3b;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    }

    * {
      box-sizing: border-box;
    }

    body {
      min-height: 100vh;
      margin: 0;
      background:
        radial-gradient(circle at top left, rgba(37, 99, 235, 0.14), transparent 34rem),
        linear-gradient(135deg, #f8fafc 0%, var(--bg) 100%);
      color: var(--text);
      line-height: 1.5;
    }

    .skip-link {
      position: absolute;
      left: 1rem;
      top: 1rem;
      z-index: 10;
      transform: translateY(-150%);
      border-radius: 0.75rem;
      background: var(--text);
      color: #ffffff;
      padding: 0.75rem 1rem;
      font-weight: 700;
      text-decoration: none;
    }

    .skip-link:focus {
      transform: translateY(0);
      outline: 3px solid var(--accent);
      outline-offset: 3px;
    }

    .page-shell {
      width: min(100% - 2rem, 58rem);
      margin: 0 auto;
      padding: 4rem 0;
    }

    .hero {
      margin-bottom: 1.5rem;
      text-align: center;
    }

    .eyebrow {
      display: inline-flex;
      margin: 0 0 0.875rem;
      border: 1px solid rgba(37, 99, 235, 0.25);
      border-radius: 999px;
      background: var(--accent-soft);
      color: #1e3a8a;
      padding: 0.35rem 0.75rem;
      font-size: 0.875rem;
      font-weight: 700;
      letter-spacing: 0.01em;
    }

    h1 {
      margin: 0;
      font-size: clamp(2.25rem, 8vw, 4.75rem);
      letter-spacing: -0.06em;
      line-height: 0.95;
    }

    .intro {
      max-width: 40rem;
      margin: 1rem auto 0;
      color: var(--muted);
      font-size: 1.125rem;
    }

    .quiz-card {
      border: 1px solid rgba(209, 213, 219, 0.8);
      border-radius: 1.5rem;
      background: rgba(255, 255, 255, 0.86);
      box-shadow: 0 1.5rem 4rem rgba(15, 23, 42, 0.12);
      padding: clamp(1rem, 4vw, 2rem);
      backdrop-filter: blur(18px);
    }

    form {
      display: grid;
      gap: 1rem;
    }

    .form-field {
      border: 1px solid var(--border);
      border-radius: 1.125rem;
      background: var(--surface);
      padding: clamp(1rem, 3vw, 1.5rem);
    }

    fieldset {
      min-width: 0;
      margin: 0;
      border: 0;
      padding: 0;
    }

    legend {
      margin: 0 0 0.75rem;
      padding: 0;
      color: var(--text);
      font-size: 1.125rem;
      font-weight: 800;
      line-height: 1.3;
    }

    .help-text {
      margin: -0.25rem 0 1rem;
      color: var(--muted);
      font-size: 0.95rem;
    }

    .choices {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 0.75rem;
    }

    .choice {
      display: flex;
      align-items: flex-start;
      gap: 0.75rem;
      min-height: 3.25rem;
      border: 1px solid var(--border);
      border-radius: 0.875rem;
      background: var(--surface-muted);
      padding: 0.9rem;
      color: var(--text);
      font-weight: 700;
      cursor: pointer;
      transition: border-color 160ms ease, background-color 160ms ease, box-shadow 160ms ease, transform 160ms ease;
    }

    .choice:hover {
      border-color: rgba(37, 99, 235, 0.55);
      background: #eff6ff;
      transform: translateY(-1px);
    }

    .choice input {
      width: 1.25rem;
      height: 1.25rem;
      margin: 0.125rem 0 0;
      accent-color: var(--accent);
      flex: 0 0 auto;
    }

    .choice:has(input:checked) {
      border-color: var(--accent);
      background: var(--accent-soft);
      box-shadow: inset 0 0 0 1px var(--accent);
    }

    .choice:has(input:focus-visible) {
      outline: 3px solid var(--ring);
      outline-offset: 3px;
    }

    .choice input:focus {
      outline: none;
    }

    .actions {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      padding-top: 0.5rem;
    }

    button {
      border: 0;
      border-radius: 999px;
      background: var(--accent);
      color: #ffffff;
      padding: 0.9rem 1.4rem;
      font: inherit;
      font-weight: 800;
      cursor: pointer;
      box-shadow: 0 0.75rem 1.5rem rgba(37, 99, 235, 0.25);
      transition: background-color 160ms ease, transform 160ms ease;
    }

    button:hover {
      background: var(--accent-strong);
      transform: translateY(-1px);
    }

    button:focus-visible {
      outline: 3px solid var(--ring);
      outline-offset: 3px;
    }

    .status {
      min-height: 1.5rem;
      margin: 0;
      color: var(--muted);
      font-weight: 700;
    }

    .status:not(:empty) {
      border: 1px solid var(--success-border);
      border-radius: 0.875rem;
      background: var(--success-bg);
      color: var(--success-text);
      padding: 0.75rem 1rem;
    }

    @media (max-width: 42rem) {
      .page-shell {
        width: min(100% - 1rem, 58rem);
        padding: 1rem 0;
      }

      .hero {
        text-align: left;
      }

      .choices {
        grid-template-columns: 1fr;
      }

      .actions {
        align-items: stretch;
        flex-direction: column;
      }

      button {
        width: 100%;
      }
